use AlexCuadra\EditorialSourceExperiment as X;
global $wpdb;$GLOBALS['mcp_checks']=0;$GLOBALS['mcp_seq']=0;
function mcp_check($ok,$label){$GLOBALS['mcp_checks']++;if(!$ok){throw new RuntimeException('OPERATING_MCP: '.$label);}}
function mcp_rpc($method,$params,$auth=null,$session=null){
 $h=['Content-Type'=>'application/json','Accept'=>'application/json, text/event-stream'];if(!empty($GLOBALS['mcp_test_fault'])){$h['X-Operating-Test-Failure']='1';}if($auth){$h['Authorization']=$auth;}if($session){$h['Mcp-Session-Id']=$session;$h['MCP-Protocol-Version']='2025-11-25';}
 $payload=['jsonrpc'=>'2.0','method'=>$method,'params'=>$params];if(!str_starts_with($method,'notifications/')){$payload['id']=++$GLOBALS['mcp_seq'];}
 $r=wp_remote_post('http://wordpress/?rest_route=/mcp/mcp-adapter-default-server',['headers'=>$h,'body'=>wp_json_encode($payload),'timeout'=>20,'redirection'=>0]);
 if(is_wp_error($r)){throw new RuntimeException('MCP_HTTP_FAILED');}return ['status'=>wp_remote_retrieve_response_code($r),'json'=>json_decode(wp_remote_retrieve_body($r),true),'session'=>wp_remote_retrieve_header($r,'mcp-session-id')];
}
function mcp_data($r){$v=$r['json']['result']??[];if(isset($v['structuredContent'])){return $v['structuredContent'];}foreach($v['content']??[] as $item){if(($item['type']??null)==='text'){$d=json_decode($item['text'],true);if(is_array($d)){return $d;}}}return null;}
function mcp_failed($r){$d=mcp_data($r);return $r['status']>=400||isset($r['json']['error'])||($r['json']['result']['isError']??false)||($d['success']??null)===false;}
function mcp_call($name,$input,$auth,$session){return mcp_rpc('tools/call',['name'=>'mcp-adapter-execute-ability','arguments'=>['ability_name'=>'alexcuadra/'.$name,'parameters'=>$input]],$auth,$session);}
function mcp_value($r){mcp_check(!mcp_failed($r),'successful tool response');$d=mcp_data($r);mcp_check(($d['success']??false)&&is_array($d['data']??null),'adapter typed result');return $d['data'];}
function mcp_identity($id){$p=WP_Application_Passwords::create_new_application_password($id,['name'=>'Synthetic operating MCP']);if(is_wp_error($p)){throw new RuntimeException('MCP_PASSWORD_SETUP');}$auth='Basic '.base64_encode(get_userdata($id)->user_login.':'.$p[0]);$r=mcp_rpc('initialize',['protocolVersion'=>'2025-11-25','capabilities'=>new stdClass(),'clientInfo'=>['name'=>'synthetic-operating','version'=>'1']],$auth);mcp_check($r['status']===200&&is_string($r['session'])&&$r['session']!=='','initialize');$n=mcp_rpc('notifications/initialized',new stdClass(),$auth,$r['session']);mcp_check(in_array($n['status'],[200,202],true),'initialized notification');return [$auth,$r['session']];}
function mcp_user($name,$apply=true){$id=wp_insert_user(['user_login'=>'mcp_operating_'.$name,'user_pass'=>wp_generate_password(),'role'=>'subscriber','user_email'=>$name.'@example.invalid']);if(is_wp_error($id)){throw new RuntimeException('MCP_USER_SETUP');}$u=get_userdata($id);foreach(['alexcuadra_read_public_projects','alexcuadra_prepare_project_changes'] as $cap){$u->add_cap($cap);}if($apply){$u->add_cap(X\OperatingContract::APPLY);$u->add_cap(X\OperatingContract::RECOVER);}return $id;}
wp_set_current_user(1);$ids=[];foreach(['en','es'] as $lang){$id=wp_insert_post(['post_type'=>'project','post_status'=>'publish','post_title'=>'MCP operating '.$lang,'post_content'=>'MCP original '.$lang],true);pll_set_post_language($id,$lang);update_field('field_676dcb2aec8d4','MCP before '.$lang,$id);$ids[$lang]=$id;}pll_save_post_translations($ids);
$owner=mcp_user('owner');$foreign=mcp_user('foreign');$prepareOnly=mcp_user('prepare-only',false);[$auth,$session]=mcp_identity($owner);[$otherAuth,$otherSession]=mcp_identity($foreign);[$deniedAuth,$deniedSession]=mcp_identity($prepareOnly);[$adminAuth,$adminSession]=mcp_identity(1);
$anonymous=mcp_rpc('initialize',['protocolVersion'=>'2025-11-25','capabilities'=>new stdClass(),'clientInfo'=>['name'=>'anonymous','version'=>'1']]);mcp_check($anonymous['status']>=400||isset($anonymous['json']['error']),'anonymous denied');
$list=mcp_data(mcp_rpc('tools/call',['name'=>'mcp-adapter-discover-abilities','arguments'=>new stdClass()],$auth,$session));$names=array_column($list['abilities']??[],'name');
foreach(X\operating_ability_specs() as $name=>$spec){mcp_check(in_array('alexcuadra/'.$name,$names,true),'discovered '.$name);$info=mcp_data(mcp_rpc('tools/call',['name'=>'mcp-adapter-get-ability-info','arguments'=>['ability_name'=>'alexcuadra/'.$name]],$auth,$session));mcp_check(($info['input_schema']['additionalProperties']??null)===false,'closed input '.$name);}
foreach(['approve-project-review','accept-operating-storage','migrate-operating-storage','audit-operating-storage'] as $name){mcp_check(!in_array('alexcuadra/'.$name,$names,true),'operator action absent');}
$proposal=mcp_value(mcp_call('create-project-change',['project_id'=>$ids['en'],'locale'=>'en','patch'=>['tagline'=>'MCP approved value'],'request_id'=>bin2hex(random_bytes(16))],$auth,$session));
$input=['proposal_id'=>$proposal['proposal_id'],'locale'=>'en','expected_proposal_version'=>$proposal['version'],'expected_base_version'=>$proposal['base_version'],'request_id'=>bin2hex(random_bytes(16))];
foreach([[$deniedAuth,$deniedSession],[$adminAuth,$adminSession]] as [$a,$s]){mcp_check(mcp_failed(mcp_call('prepare-project-application',$input,$a,$s)),'prepare-only/admin without apply denied');}
$bad=$input;$bad['force']=true;mcp_check(mcp_failed(mcp_call('prepare-project-application',$bad,$auth,$session)),'extra input rejected');
$review=mcp_value(mcp_call('prepare-project-application',$input,$auth,$session));mcp_check(mcp_value(mcp_call('prepare-project-application',$input,$auth,$session))===$review,'prepare replay');
$inspection=mcp_value(mcp_call('inspect-project-review',['review_id'=>$review['review_id'],'locale'=>'en'],$auth,$session));mcp_check($inspection['document']['operation']==='apply'&&$inspection['review_hash']===$review['review_hash'],'review typed inspection');
mcp_check(mcp_failed(mcp_call('inspect-project-review',['review_id'=>$review['review_id'],'locale'=>'en'],$otherAuth,$otherSession)),'foreign review denied');
$apply=['review_id'=>$review['review_id'],'locale'=>'en','expected_review_hash'=>$review['review_hash'],'request_id'=>bin2hex(random_bytes(16))];mcp_check(mcp_failed(mcp_call('apply-project-review',$apply,$auth,$session)),'approval required over MCP');mcp_check(get_post_meta($ids['en'],'project_tagline',true)==='MCP before en','failed apply preserves source');
$c=new X\OperatingContract($wpdb,source_operation($wpdb),'snapshot','field_schema','cache_clear');get_userdata(1)->add_cap(X\OperatingContract::APPROVE);wp_set_current_user(0);wp_set_current_user(1);$c->approve($review['review_id'],'en',$review['review_hash']);
$app=mcp_value(mcp_call('apply-project-review',$apply,$auth,$session));mcp_check($app['content_state']==='applied','approved apply over MCP');mcp_check(mcp_value(mcp_call('apply-project-review',$apply,$auth,$session))===$app,'application replay');
$recovery=mcp_value(mcp_call('prepare-project-recovery',['proposal_id'=>$proposal['proposal_id'],'locale'=>'en','expected_source_version'=>$app['source_version'],'request_id'=>bin2hex(random_bytes(16))],$auth,$session));
$inverse=mcp_value(mcp_call('inspect-project-review',['review_id'=>$recovery['review_id'],'locale'=>'en'],$auth,$session));mcp_check($inverse['document']['operation']==='recover','recovery inspection output schema');
$recover=['review_id'=>$recovery['review_id'],'locale'=>'en','expected_review_hash'=>$recovery['review_hash'],'request_id'=>bin2hex(random_bytes(16))];mcp_check(mcp_failed(mcp_call('recover-project-review',$recover,$auth,$session)),'fresh recovery approval required');$c->approve($recovery['review_id'],'en',$recovery['review_hash']);
$restored=mcp_value(mcp_call('recover-project-review',$recover,$auth,$session));mcp_check($restored['content_state']==='recovered'&&$restored['application_event']===$app['event_id'],'approved recovery over MCP');mcp_check(mcp_value(mcp_call('recover-project-review',$recover,$auth,$session))===$restored,'recovery replay');
$state=mcp_value(mcp_call('get-project-effect-state',['proposal_id'=>$proposal['proposal_id'],'locale'=>'en'],$auth,$session));mcp_check($state['event_id']===$restored['event_id']&&$state['effect_state']==='pending','latest effect metadata');cache_clear($ids['en']);mcp_check(get_post_meta($ids['en'],'project_tagline',true)==='MCP before en'&&get_post_meta($ids['es'],'project_tagline',true)==='MCP before es','both language values preserved');
$routes=rest_do_request(new WP_REST_Request('GET','/wp-abilities/v1/abilities'));mcp_check(!str_contains(wp_json_encode($routes->get_data()),'alexcuadra/apply-project-review'),'core REST discovery hidden');
$error=X\operating_ability_error(new RuntimeException('SQL secret /private/path'));mcp_check($error->get_error_code()==='editorial_operation_failed'&&!str_contains($error->get_error_message(),'secret'),'internal failure sanitized');
$reuse=mcp_rpc('tools/list',new stdClass(),$otherAuth,$session);mcp_check(mcp_failed($reuse),'foreign session reuse denied');
get_userdata($owner)->remove_cap(X\OperatingContract::APPLY);try{mcp_check(mcp_failed(mcp_call('apply-project-review',$apply,$auth,$session)),'revoked apply blocks receipt replay');}finally{get_userdata($owner)->add_cap(X\OperatingContract::APPLY);}
$GLOBALS['mcp_test_fault']=true;try{$safe=mcp_call('get-project-effect-state',['proposal_id'=>$proposal['proposal_id'],'locale'=>'en'],$auth,$session);mcp_check(mcp_failed($safe)&&!str_contains(wp_json_encode($safe),'SYNTHETIC_PRIVATE_FAILURE'),'internal factory fault sanitized over HTTP');}finally{$GLOBALS['mcp_test_fault']=false;}
echo 'SOURCE_OPERATING_MCP_RESULT='.wp_json_encode(['checks'=>$GLOBALS['mcp_checks'],'passed'=>true,'transport'=>'official MCP adapter JSON-RPC HTTP','abilities'=>6,'approvalExposed'=>false,'credentials'=>'synthetic Application Passwords','liveCmsModified'=>false]).PHP_EOL;
